import {makeTerrain,inside,linkProfile,resolveRadio,PRESETS} from './physics.mjs';
const $=id=>document.getElementById(id), points={기지:[3500,3500],A:[3250,4500],B:[2000,4500],C:[1750,3250],D:[500,3000],목표:[500,4250]}, heights={기지:4,A:3,B:3,C:3,D:3,목표:2},radio=resolveRadio(PRESETS.sband),selected=new Set();let terrain,edges=[];
function draw(){const active=new Set(['기지','A','B','목표',...selected]);$('count').textContent=`추가 설치 ${selected.size} / 1개 · A와 B는 기존 중계소`;document.querySelectorAll('[data-id]').forEach(b=>{const yes=selected.has(b.dataset.id);b.setAttribute('aria-pressed',String(yes));b.textContent=`중계소 ${b.dataset.id} ${yes?'철거':'설치'}`});$('check').disabled=!terrain||!selected.size;$('markers').innerHTML=Object.entries(points).map(([id,[x,y]])=>`<circle cx="${x}" cy="${y}" r="65" fill="${active.has(id)?'#f4ac78':'#323c2e'}" stroke="white" stroke-width="10"/><text x="${x+75}" y="${y-30}" fill="white" font-size="85">${id}</text>`).join('');$('lines').innerHTML='';$('result').hidden=true;if(window.parent!==window)window.parent.postMessage({type:'level5-result',success:false},location.origin);}
for(const id of ['C','D']){let b=document.createElement('button');b.className='candidate';b.dataset.id=id;b.onclick=()=>{selected.has(id)?selected.delete(id):selected.size<1&&selected.add(id);draw()};$('buttons').append(b)}
$('reset').onclick=()=>{selected.clear();draw()};
function analyze(a,b){const v=linkProfile(terrain,radio,...points[a],heights[a],...points[b],heights[b],terrain.res);const valid=[...v.d,...v.zFlat].every(Number.isFinite),gap=Math.max(...Array.from(v.d,(d,i)=>v.zFlat[i]-(v.za+(v.zb-v.za)*d/v.D)).slice(1,-1));return {a,b,valid,visible:valid&&gap<=0,margin:v.margin,ok:valid&&gap<=0&&v.margin>=3};}
$('check').onclick=()=>{const nodes=['기지','A','B',...selected,'목표'];edges=[];for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++)edges.push(analyze(nodes[i],nodes[j]));const queue=[['기지']],seen=new Set(['기지']);let route=null;while(queue.length){let path=queue.shift(),p=path.at(-1);if(p==='목표'){route=path;break}for(const e of edges){if(!e.ok)continue;const n=e.a===p?e.b:e.b===p?e.a:null;if(n&&!seen.has(n)){seen.add(n);queue.push([...path,n]);}}} $('lines').innerHTML=edges.map(e=>`<line x1="${points[e.a][0]}" y1="${points[e.a][1]}" x2="${points[e.b][0]}" y2="${points[e.b][1]}" stroke="${e.ok?'#8cd7b0':'#ff876c'}" stroke-dasharray="${e.ok?'0':'40 35'}" stroke-width="15"/>`).join('');$('result').hidden=false;$('result').innerHTML=`<h2>${route?'통신망 확장 성공 · 전체 미션 완료':'목표까지 연결되지 않았어요'}</h2><p>${route?'연결 경로: '+route.join(' → '):'설치한 중계소의 연결 상태를 보고 다른 위치를 추가하거나 바꿔보세요.'}</p><details><summary>구간별 결과 보기</summary><ul>${edges.map(e=>`<li>${e.a} → ${e.b}: ${!e.valid?'지형 자료 부족':`가시선 ${e.visible?'확보':'가림'} · 신호 여유 ${e.margin.toFixed(1)} dB`}</li>`).join('')}</ul></details><p>${route?"LEVEL 1~5를 완료했습니다! ":""}고도 표본과 교육용 장비 설정을 이용한 시뮬레이션입니다.</p>`;if(window.parent!==window)window.parent.postMessage({type:'level5-result',success:!!route},location.origin);};
try{const [m,b]=await Promise.all([fetch('./data/meta.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('./data/terrain_8m.f32').then(r=>{if(!r.ok)throw Error();return r.arrayBuffer()})]);terrain=makeTerrain(b,m);if(!Object.values(points).every(p=>inside(terrain,...p)))throw Error();draw()}catch(e){$('result').hidden=false;$('result').textContent='지형 자료를 불러오지 못했습니다.'}
